'use client';

import React from 'react';

/** Upload state for a file attachment. */
export type FileAttachmentState = 'uploading' | 'done' | 'error';

/** Props for the {@link FileAttachment} component. */
export interface FileAttachmentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** File name. */
  name: string;
  /** Human-readable file size string (e.g. "2.4 MB"). */
  size?: string;
  /** File icon character or emoji. */
  icon?: string;
  /** Current upload state. */
  state?: FileAttachmentState;
  /** Upload progress (0-100). Drives the progress bar width via CSS variable. */
  progress?: number;
  /** Called when the remove button is clicked. */
  onRemove?: () => void;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * File upload pill with progress bar and remove button.
 * Renders a `<div>` with `sk-file-attachment` and `data-state`.
 */
export const FileAttachment = React.forwardRef<HTMLDivElement, FileAttachmentProps>(
  ({ name, size, icon, state, progress, onRemove, className, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-file-attachment${className ? ` ${className}` : ''}`}
      data-state={state}
      style={{ '--_progress': progress !== undefined ? `${progress}%` : undefined } as React.CSSProperties}
      {...rest}
    >
      <div className="sk-file-attachment__progress" />
      {icon && <span className="sk-file-attachment__icon">{icon}</span>}
      <span className="sk-file-attachment__name">{name}</span>
      {size && <span className="sk-file-attachment__size">{size}</span>}
      {onRemove && (
        <button className="sk-file-attachment__remove" onClick={onRemove} aria-label="Remove file">
          x
        </button>
      )}
    </div>
  ),
);

FileAttachment.displayName = 'FileAttachment';

/** Props for the {@link FileAttachments} list wrapper. */
export interface FileAttachmentsProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Flex-wrap container for multiple FileAttachment pills. */
export const FileAttachments = React.forwardRef<HTMLDivElement, FileAttachmentsProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-file-attachments${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

FileAttachments.displayName = 'FileAttachments';

/**
 * skeehn — FileAttachment Component
 *
 * @component sk-file-attachment
 * @states    [data-state="uploading"|"error"|"done"] | [data-skeleton]
 * @slots     __progress __icon __name __size __remove
 * @container sk-file-attachments (flex wrapper)
 * @a11y      Focus ring on remove, state via border + text + icon
 * @design    Taller progress, readable size, bigger remove target, done success state.
 */

.sk-file-attachment {
  display: inline-flex; align-items: center; gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-2) var(--sk-space-2) var(--sk-space-3);
  border: var(--sk-border); border-radius: var(--sk-radius-sm);
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-foreground)); background: hsl(var(--sk-surface));
  max-width: 300px; position: relative; overflow: hidden;
  transition: transform var(--sk-transition-fast), border-color var(--sk-transition-fast);
}
.sk-file-attachment:hover { transform: translateY(-1px); }

/* Progress bar (var-driven) */
.sk-file-attachment__progress { position: absolute; bottom: 0; left: 0; height: 3px; background: hsl(var(--sk-accent)); width: var(--_progress, 0%); transition: width 0.2s ease; }
.sk-file-attachment[data-state="uploading"] .sk-file-attachment__progress { animation: sk-progress-indeterminate 1s ease infinite; }

/* State variants */
.sk-file-attachment[data-state="uploading"] { border-color: hsl(var(--sk-muted-foreground) / 0.4); }
.sk-file-attachment[data-state="error"] { border-color: hsl(var(--sk-destructive)); color: hsl(var(--sk-destructive)); }
.sk-file-attachment[data-state="done"] { border-color: hsl(var(--sk-success) / 0.6); }
.sk-file-attachment[data-state="done"] .sk-file-attachment__icon { color: hsl(var(--sk-success)); }

.sk-file-attachment__icon { flex-shrink: 0; font-size: 0.95rem; color: hsl(var(--sk-muted-foreground)); }
.sk-file-attachment__name { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.sk-file-attachment__size { flex-shrink: 0; color: hsl(var(--sk-muted-foreground) / 0.75); font-size: var(--sk-font-size-xs); }
.sk-file-attachment__remove {
  flex-shrink: 0; background: none; border: none;
  padding: var(--sk-space-1) var(--sk-space-2); cursor: pointer;
  color: hsl(var(--sk-muted-foreground)); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); line-height: 1;
  border-radius: var(--sk-radius-control); transition: color var(--sk-transition), background var(--sk-transition);
}
.sk-file-attachment__remove:hover { color: hsl(var(--sk-destructive)); background: hsl(var(--sk-destructive) / 0.1); }
.sk-file-attachment__remove:focus-visible { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); }

.sk-file-attachments { display: flex; flex-wrap: wrap; gap: var(--sk-space-2); padding: var(--sk-space-2) 0; }

/* Skeleton */
.sk-file-attachment[data-skeleton] {
  pointer-events: none; color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite;
  border-color: transparent; min-width: 8rem; min-height: 1.5rem;
}
.sk-file-attachment[data-skeleton] .sk-file-attachment__remove,
.sk-file-attachment[data-skeleton] .sk-file-attachment__progress { display: none; }

@media print { .sk-file-attachment, .sk-file-attachments { display: none; } }
@media (prefers-reduced-motion: reduce) {
  .sk-file-attachment, .sk-file-attachment__remove { transition: none; }
  .sk-file-attachment:hover { transform: none; }
  .sk-file-attachment__progress { animation: none; }
  .sk-file-attachment[data-skeleton] { animation: none; background: hsl(var(--sk-muted)); }
}
